    summary = #{article.summary}, cover_url = #{article.coverUrl}, article_type = #{article.articleType},
    original_url = #{article.originalUrl}, status = #{article.status}, visibility = #{article.visibility},
    is_top = #{article.isTop}, allow_comment = #{article.allowComment},
    publish_time = #{article.publishTime}, deleted_at = #{article.deletedAt}
WHERE article_id = #{article.articleId} AND author_id = #{author}

